#!/usr/bin/env node
/**
 * setup-github-repo.js
 *
 * Run once after creating your repo from this template.
 * Sets the repo description, topics, homepage, and uploads the social preview cover.
 *
 * Usage:
 *   node .github/scripts/setup-github-repo.js
 *
 * Requirements:
 *   - GitHub CLI installed: https://cli.github.com
 *   - Authenticated: gh auth login
 *   - OR set GITHUB_TOKEN env var manually
 */

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

// ─────────────────────────────────────────────
// CONFIGURE THESE FOR YOUR PROJECT
// ─────────────────────────────────────────────
const CONFIG = {
  // Your GitHub username or org
  owner: process.env.GITHUB_OWNER || '',

  // Your repo name
  repo: process.env.GITHUB_REPO || '',

  // Short description shown in the About sidebar (max ~350 chars)
  description: 'Replace this with your project description',

  // Homepage URL (optional — shown next to description)
  homepage: '',

  // Topics / tags (max 20, lowercase, hyphen-separated)
  topics: [
    'template',
    // Add your stack: 'nodejs', 'python', 'go', 'rust', 'react', etc.
    // Add your domain: 'api', 'cli', 'ml', 'data-pipeline', 'devtools', etc.
  ],

  // Path to your social preview image (generated by this template)
  socialPreviewPath: path.join(__dirname, '../../docs/social-preview.png'),
};
// ─────────────────────────────────────────────

function run(cmd) {
  return execSync(cmd, { encoding: 'utf8' }).trim();
}

function getToken() {
  if (process.env.GITHUB_TOKEN) return process.env.GITHUB_TOKEN;
  try {
    return run('gh auth token');
  } catch {
    console.error('❌ No GITHUB_TOKEN found. Run: gh auth login');
    process.exit(1);
  }
}

async function main() {
  if (!CONFIG.owner || !CONFIG.repo) {
    // Auto-detect from git remote
    try {
      const remote = run('git remote get-url origin');
      const match = remote.match(/github\.com[:/](.+?)\/(.+?)(\.git)?$/);
      if (match) {
        CONFIG.owner = CONFIG.owner || match[1];
        CONFIG.repo  = CONFIG.repo  || match[2];
      }
    } catch {}
  }

  if (!CONFIG.owner || !CONFIG.repo) {
    console.error('❌ Could not detect owner/repo. Set GITHUB_OWNER and GITHUB_REPO env vars.');
    process.exit(1);
  }

  const token = getToken();
  const base  = `https://api.github.com/repos/${CONFIG.owner}/${CONFIG.repo}`;
  const headers = {
    'Authorization': `Bearer ${token}`,
    'Accept': 'application/vnd.github+json',
    'X-GitHub-Api-Version': '2022-11-28',
    'Content-Type': 'application/json',
  };

  console.log(`\n📦 Setting up ${CONFIG.owner}/${CONFIG.repo}\n`);

  // 1. Update description & homepage
  console.log('📝 Setting description and homepage...');
  const repoRes = await fetch(base, {
    method: 'PATCH',
    headers,
    body: JSON.stringify({
      description: CONFIG.description,
      homepage:    CONFIG.homepage,
      has_issues:  true,
      has_projects: false,
      has_wiki:    false,
    }),
  });
  if (!repoRes.ok) {
    console.error('❌ Failed to update repo:', await repoRes.text());
  } else {
    console.log('   ✅ Description set');
  }

  // 2. Replace topics
  console.log('🏷️  Setting topics...');
  const topicsRes = await fetch(`${base}/topics`, {
    method: 'PUT',
    headers,
    body: JSON.stringify({ names: CONFIG.topics }),
  });
  if (!topicsRes.ok) {
    console.error('❌ Failed to set topics:', await topicsRes.text());
  } else {
    console.log(`   ✅ Topics: ${CONFIG.topics.join(', ')}`);
  }

  // 3. Upload social preview (requires GitHub CLI — API doesn't expose this endpoint)
  if (fs.existsSync(CONFIG.socialPreviewPath)) {
    console.log('🖼️  Uploading social preview...');
    try {
      // gh api doesn't support multipart directly; use curl via execSync
      run(
        `curl -s -o /dev/null -w "%{http_code}" ` +
        `-X PUT "https://api.github.com/repos/${CONFIG.owner}/${CONFIG.repo}/social_preview" ` +
        `-H "Authorization: Bearer ${token}" ` +
        `-H "Accept: application/vnd.github+json" ` +
        `-F "image=@${CONFIG.socialPreviewPath}"`,
      );
      console.log('   ✅ Social preview uploaded');
    } catch {
      console.warn('   ⚠️  Social preview upload failed (may need browser — see note below)');
    }
  } else {
    console.warn(`   ⚠️  Social preview not found at: ${CONFIG.socialPreviewPath}`);
    console.warn('      Generate it first: node .github/scripts/generate-preview.js');
  }

  console.log(`
✅ Done! View your repo at:
   https://github.com/${CONFIG.owner}/${CONFIG.repo}

⚠️  Note: GitHub's social preview upload endpoint is not public.
   If the image didn't upload automatically, go to:
   Settings → General → Social preview → Edit → upload docs/social-preview.png
`);
}

main().catch(console.error);
